styl:
.b-new-footer-03 .socials {  display: inline-block;
  font-size: 0;
  margin: 0 auto;  }
@media screen and (max-width: 600px) {
  .b-new-footer-03 .socials {  width: 100% !important;  }
}
.b-new-footer-03 .socials a {  display: inline-block;
  vertical-align: middle;
  margin: 0 15px;  }
@media screen and (max-width: 600px) {
  .b-new-footer-03 .socials a {  margin-bottom: 10px !important;  }
}
.b-new-footer-03 .soc-icon {  float: none;
  max-width: 24px;  }
.b-new-footer-03 .socials {  display: block;
  font-size: 0;
  margin: 0 auto;
  text-align: center;  }
.b-new-footer-03 .soc-icon {  float: none !important;
  max-width: 24px;  }
@media screen and (max-width:600px) {
  .b-new-footer-03 .socials {  width:100%!important  }
}
@media screen and (max-width:600px) {
  .b-new-footer-03 .socials a {  margin-bottom:10px!important  }
}
.b-new-footer-03 .socials {  display:block;font-size:0;margin:0 auto;text-align:center  }
.b-new-footer-03 .arrow-icon, .b-new-footer-03 .socials a {  display:inline-block;vertical-align:middle  }
.b-new-footer-03 .socials a {  margin:0 15px  }
.b-new-footer-03 .arrow-icon, .b-new-footer-03 .soc-icon {  float:none!important;max-width:24px  }
